INSERT INTO public.vehicles (id, slug, name, condition, make, model, year, price, sale_price, down_payment, mileage, transmission, exterior_color, interior_color, fuel_type, body_type, engine, drivetrain, vin, title_status, trim, description, features, images, is_hot_deal, is_sold, is_featured, sort_order) VALUES (
  'b7472dfa-85de-4daa-abe4-573f6abbc35c', '1967-mercedes-benz-600-grosser-b7472dfa', '1967 Mercedes-Benz 600 Grosser', 'Used', 'Mercedes-Benz', '600 Grosser', 1967, 30000.0, 28200.0, 3000.0, '88k miles', 'Automatic', 'Factory Metallic Finish', 'Premium Comfort Interior', 'Gasoline', 'Sedan', '1967 Mercedes-Benz Multi-Valve Powertrain', 'Front-Wheel Drive', 'WDDHFB7472DFA85DX', 'Clean Title / 150-Point Certified', 'Grosser', '1967 Mercedes-Benz 600 Grosser 6.3L V8 – 88K Miles For sale is one of the most iconic luxury cars ever built, this 1967 Mercedes-Benz 600 Grosser showing 88,885 original miles. Finished in brown and highly original throughout, this example retains its original interior, full documentation, and presents as an incredibly well-preserved time capsule of Mercedes’ flagship sedan. Powered by the legendary 6.3L V8 paired with an automatic transmission, the 600 delivered unmatched power and refinement for its time. Known for its advanced hydraulic system controlling everything from windows to seats, this example is reported to be in great working order, a key detail on these cars. The driving experience is exactly what the Grosser is known for: smooth, effortless, and commanding. Highly original 600 Grossers like this are exceptionally rare to find in this condition, especially with documentation and properly maintained systems. Whether for a serious collection, concours events, or high-end shows, this is one of those cars that stands in a league of its own. Price: $30,000 Down payment 💲 3,000', ARRAY['150-Point Dealership Mechanical Inspection', 'Factory Multi-Zone Climate Control', 'Bluetooth Wireless Audio & Hands-Free Calling', 'High-Definition Rearview Camera', 'Power-Adjustable Front Seats', 'Remote Keyless Entry System', 'Tire Pressure Monitoring System (TPMS)', 'Electronic Stability & Traction Control']::TEXT[], ARRAY['https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360829141-cnk9i0uj008.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360832039-hu8rohuqtgd.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360833572-6uege2rgfo3.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360835212-ugi5o2vckni.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360836855-mcfx16pr4yq.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360839002-4yr8p4mdmx.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360840852-fzwsymj0xx.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360842894-w47etfz50ek.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360844631-rh0jjp5ml8h.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360846374-jshvcme1lvl.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360848114-erhu9puaen.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360849854-qavdfmnr4dp.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360851596-ww2nhuh4qws.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360853541-i6o2b8dp9v.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360855283-3rjgyxen0tl.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360857023-oj27tvcybv9.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360858765-xo3eduhie7s.jpeg', 'https://baljrasbrqtkpxvmwvkx.supabase.co/storage/v1/object/public/car-images/cars/1774360860009-x6ursvfa7b.jpeg']::TEXT[], FALSE, FALSE, TRUE, 37
